('Thiên nhiên', 'WORD_HUNT', 'Tập trung nhìn nhanh, tìm đủ 5 từ trong chủ đề thiên nhiên.', 5, '{"categoryKey":"nature","categoryLabel":"Thiên nhiên","boardSize":8,"timeLimitSeconds":105,"targetWordCount":5,"maxHintsPerDay":3,"objectiveText":"Mục tiêu: 5 từ","words":["RIVER","MOUNTAIN","FOREST","RAIN","CLOUD","STONE"]}'),
('Ẩm thực', 'WORD_HUNT', 'Màn đang chơi: tìm đủ 5 từ trước khi hết giờ.', 5, '{"categoryKey":"food","categoryLabel":"Ẩm thực","boardSize":10,"timeLimitSeconds":105,"targetWordCount":5,"maxHintsPerDay":3,"objectiveText":"Mục tiêu: 5 từ","words":["PIZZA","CAKE","SOUP","TACO","RICE","STEAK","BURGER"]}'),
('Du lịch', 'WORD_HUNT', 'Mở khóa sau khi hoàn thành Ẩm thực.', 5, '{"categoryKey":"travel","categoryLabel":"Du lịch","boardSize":8,"timeLimitSeconds":120,"targetWordCount":6,"maxHintsPerDay":3,"objectiveText":"Mục tiêu: 6 từ","unlockRequirementText":"Cần vượt qua Ẩm thực để mở khóa","words":["HOTEL","FLIGHT","PASSPORT","TICKET","LUGGAGE","BEACH"]}'),
('Thể thao', 'WORD_HUNT', 'Mở khóa sau khi hoàn thành Du lịch.', 5, '{"categoryKey":"sports","categoryLabel":"Thể thao","boardSize":10,"timeLimitSeconds":120,"targetWordCount":6,"maxHintsPerDay":3,"objectiveText":"Mục tiêu: 6 từ","unlockRequirementText":"Cần vượt qua Du lịch để mở khóa","words":["TENNIS","SOCCER","BOXING","RUNNING","SWIM","VOLLEY"]}'),
('Công nghệ', 'WORD_HUNT', 'Mở khóa sau khi hoàn thành Thể thao.', 5, '{"categoryKey":"technology","categoryLabel":"Công nghệ","boardSize":10,"timeLimitSeconds":150,"targetWordCount":7,"maxHintsPerDay":3,"objectiveText":"Mục tiêu: 7 từ","unlockRequirementText":"Cần vượt qua Thể thao để mở khóa","words":["SERVER","ROUTER","CODING","BINARY","MOBILE","CLOUD","SCREEN"]}');
INSERT INTO learning_lessons (title, type, description, learning_activity_id, content) VALUES
('Học việc sơ đẳng', 'WORD_RACE', 'Người đạt 40 điểm trước sẽ thắng. Chế độ luyện tập cơ bản.', 4, '{"targetScore":40,"timeLimit":20,"forbiddenEndings":[]}'),
('Nói không với số nhiều', 'WORD_RACE', 'Người đạt 50 điểm trước và không kết thúc bằng ''s'' sẽ thắng.', 4, '{"targetScore":50,"timeLimit":16,"forbiddenEndings":["s"]}'),
('E ... Em là không thể', 'WORD_RACE', 'Người đạt 50 điểm trước và không kết thúc bằng ''e'' sẽ thắng.', 4, '{"targetScore":50,"timeLimit":14,"forbiddenEndings":["e"]}'),
('Chạy đua tử thần', 'WORD_RACE', 'Thời gian diễn ra bị rút ngắn, ai đạt 50 điểm trước sẽ thắng.', 4, '{"targetScore":50,"timeLimit":10,"forbiddenEndings":[]}');
INSERT INTO learning_lessons (title, type, description, learning_activity_id, content) VALUES
                                                                                           ('Các thì (Tenses)', 'GRAMMAR_TOPIC', '12 thì cơ bản, dấu hiệu và cách dùng nhanh', 6, '{"order":1}'),
                                                                                           ('Cấu trúc câu (Structures)', 'GRAMMAR_TOPIC', 'Câu bị động, câu điều kiện, so sánh và động từ khuyết thiếu', 6, '{"order":2}'),
                                                                                           ('Mệnh đề & lời nói (Clauses)', 'GRAMMAR_TOPIC', 'Mệnh đề quan hệ, mệnh đề danh từ, mệnh đề trạng ngữ, đảo ngữ và câu tường thuật', 6, '{"order":3}');
INSERT INTO learning_lessons (title, type, description, learning_activity_id, content) VALUES
                                                                                           ('Hiện tại đơn', 'GRAMMAR_LESSON', 'Thói quen, sự thật hiển nhiên', 6, '{"order":1,"engTitle":"Present Simple","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Dùng để diễn tả một thói quen, một hành động lặp đi lặp lại hoặc một sự thật hiển nhiên.","example":"She reads a book every night."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + V(s/es)","examples":[{"text":"She reads a book every night.","translated":"Cô ấy đọc sách mỗi tối.","highlight":"reads"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["always","usually","often","sometimes","never","every day"]}]}]}'),
                                                                                           ('Hiện tại tiếp diễn', 'GRAMMAR_LESSON', 'Hành động đang xảy ra', 6, '{"order":2,"engTitle":"Present Continuous","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Dùng cho hành động đang xảy ra tại thời điểm nói.","example":"I am reading a book now."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + am/is/are + V-ing","examples":[{"text":"I am reading a book now.","translated":"Tôi đang đọc một quyển sách bây giờ.","highlight":"am reading"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["now","at the moment","right now","Look!","Listen!"]}]}]}'),
                                                                                           ('Hiện tại hoàn thành', 'GRAMMAR_LESSON', 'Hành động từ quá khứ đến hiện tại', 6, '{"order":3,"engTitle":"Present Perfect","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Diễn tả hành động xảy ra trong quá khứ liên quan đến hiện tại.","example":"I have finished my homework."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + have/has + V3/ed","examples":[{"text":"I have finished my homework.","translated":"Tôi đã làm xong bài tập.","highlight":"have finished"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["just","recently","lately","ever","never","already","yet","since","for","so far"]}]}]}'),
                                                                                           ('Hiện tại hoàn thành tiếp diễn', 'GRAMMAR_LESSON', 'Sự liên tục của hành động từ quá khứ', 6, '{"order":4,"engTitle":"Present Perfect Continuous","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Nhấn mạnh quá trình của hành động bắt đầu trong quá khứ và tiếp tục đến hiện tại.","example":"I have been waiting for 2 hours."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + have/has + been + V-ing","examples":[{"text":"I have been waiting for 2 hours.","translated":"Tôi đã chờ 2 tiếng.","highlight":"have been waiting"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["all day/week","for the whole month","since","for"]}]}]}'),
                                                                                           ('Quá khứ đơn', 'GRAMMAR_LESSON', 'Hành động đã xảy ra và chấm dứt trong quá khứ', 6, '{"order":5,"engTitle":"Past Simple","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Một hành động diễn ra tại một thời điểm xác định trong quá khứ và đã kết thúc hoàn toàn.","example":"I went to school yesterday."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + V-ed/V2","examples":[{"text":"I went to school yesterday.","translated":"Tôi đã đi học hôm qua.","highlight":"went"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["yesterday","last","ago","in + năm quá khứ"]}]}]}'),
                                                                                           ('Quá khứ tiếp diễn', 'GRAMMAR_LESSON', 'Hành động đang xảy ra tại thời điểm quá khứ cụ thể', 6, '{"order":6,"engTitle":"Past Continuous","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Hành động đang diễn ra tại một thời điểm xác định trong quá khứ hoặc một hành động đang làm thì bị một hành động khác xen vào.","example":"I was sleeping when she called."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + was/were + V-ing","examples":[{"text":"I was sleeping when she called.","translated":"Tôi đang ngủ khi cô ấy gọi tới.","highlight":"was sleeping"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["at + giờ + yesterday","at this time last week","when","while"]}]}]}'),
                                                                                           ('Quá khứ hoàn thành', 'GRAMMAR_LESSON', 'Hành động xảy ra trước một hành động quá khứ khác', 6, '{"order":7,"engTitle":"Past Perfect","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Hành động đã hoàn thành trước một thời điểm hoặc hành động khác trong quá khứ.","example":"I had eaten before I arrived."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + had + V3/ed","examples":[{"text":"I had eaten before I arrived.","translated":"Tôi đã ăn trước khi đến.","highlight":"had eaten"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["by the time","prior to","before","after"]}]}]}'),
                                                                                           ('Quá khứ hoàn thành tiếp diễn', 'GRAMMAR_LESSON', 'Tính liên tục của hành động xảy ra trước quá khứ', 6, '{"order":8,"engTitle":"Past Perfect Continuous","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Nhấn mạnh quá trình, thời gian diễn ra của hành động trước một hành động quá khứ khác.","example":"I had been waiting for 2 hours before she arrived."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + had + been + V-ing","examples":[{"text":"I had been waiting for 2 hours before she arrived.","translated":"Tôi đã chờ suốt 2 tiếng trước khi cô ấy đến.","highlight":"had been waiting"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["for","since","how long","before"]}]}]}'),
                                                                                           ('Tương lai đơn', 'GRAMMAR_LESSON', 'Quyết định tức thời, dự đoán, hứa hẹn', 6, '{"order":9,"engTitle":"Future Simple","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Một hành động sẽ xảy ra trong tương lai không dự định trước, quyết định tại lúc nói hoặc dựa dẫm vào quan điểm cá nhân.","example":"I will help you."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + will + V","examples":[{"text":"I will help you.","translated":"Tôi sẽ giúp bạn.","highlight":"will help"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["tomorrow","next","in + thời gian tới","think","believe","hope"]}]}]}'),
                                                                                           ('Tương lai tiếp diễn', 'GRAMMAR_LESSON', 'Hành động sẽ đang xảy ra tại một thời điểm tương lai', 6, '{"order":10,"engTitle":"Future Continuous","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Hành động dự kiến đang diễn ra tại một thời điểm cụ thể trong tương lai.","example":"I will be sleeping at 10 PM tonight."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + will + be + V-ing","examples":[{"text":"I will be sleeping at 10 PM tonight.","translated":"Tôi sẽ đang ngủ lúc 10 giờ tối nay.","highlight":"will be sleeping"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["at + giờ + tomorrow","at this time next","when/while + HTĐ"]}]}]}'),
                                                                                           ('Tương lai hoàn thành', 'GRAMMAR_LESSON', 'Hành động sẽ hoàn tất trước điểm tương lai', 6, '{"order":11,"engTitle":"Future Perfect","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Hành động sẽ được hoàn tất trước một thời điểm cụ thể hoặc trước một hành động khác trong tương lai.","example":"I will have finished the report by tomorrow."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + will + have + V3/ed","examples":[{"text":"I will have finished the report by tomorrow.","translated":"Tôi sẽ hoàn thành báo cáo trước ngày mai.","highlight":"will have finished"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["by + mốc thời gian tương lai","by the time + HTĐ","before + HTĐ"]}]}]}'),
                                                                                           ('Tương lai hoàn thành tiếp diễn', 'GRAMMAR_LESSON', 'Quá trình dài tới mốc điểm tương lai', 6, '{"order":12,"engTitle":"Future Perfect Continuous","sections":[{"id":1,"title":"Cách sử dụng","type":"usage","items":[{"icon":"book-open-page-variant","title":"Ý nghĩa","description":"Nhấn mạnh tính liên tục khoảng thời gian một hành động sẽ kéo dài cho đến mốc ở tương lai.","example":"By next year, I will have been working here for 5 years."}]},{"id":2,"title":"Cấu trúc","type":"formula","formula":"S + will + have + been + V-ing","examples":[{"text":"By next year, I will have been working here for 5 years.","translated":"Tới năm sau, tôi sẽ làm việc ở đây được 5 năm.","highlight":"will have been working"}]},{"id":3,"title":"Dấu hiệu nhận biết","type":"markers","groups":[{"title":"Dấu hiệu","items":["by the time + HTĐ","for + khoảng thời gian","by + mốc thời gian"]}]}]}'),
                                                                                           ('Câu bị động', 'GRAMMAR_LESSON', 'Từ chủ động sang bị động ở nhiều thì thông dụng', 6, '{"order":1,"engTitle":"Passive Voice","sections":[{"id":1,"title":"1. Công thức","type":"formula","formula":"S + be + V3/ed + (by O)","examples":[{"text":"The letter was sent yesterday.","translated":"Lá thư đã được gửi hôm qua.","highlight":"was sent"},{"text":"English is spoken worldwide.","translated":"Tiếng Anh được nói trên toàn thế giới.","highlight":"is spoken"}]},{"id":2,"title":"2. Cách dùng","type":"usage","items":[{"icon":"account-tie","title":"Khi không muốn nhấn mạnh người làm","description":"Tập trung vào hành động hoặc kết quả.","example":"The room was cleaned."},{"icon":"layers","title":"Báo cáo, tin tức","description":"Thường dùng trong văn viết trang trọng.","example":"The project was approved."}]}]}'),
                                                                                           ('Câu điều kiện', 'GRAMMAR_LESSON', 'Các loại câu điều kiện từ zero đến mixed', 6, '{"order":2,"engTitle":"Conditional Sentences","sections":[{"id":1,"title":"1. Các loại câu điều kiện","type":"usage","items":[{"icon":"numeric-0-box","title":"Zero conditional","description":"Sự thật hiển nhiên","example":"If you heat ice, it melts."},{"icon":"numeric-1-box","title":"First conditional","description":"Khả năng ở hiện tại/tương lai","example":"If it rains, we will stay home."},{"icon":"numeric-2-box","title":"Second / third conditional","description":"Giả định không có thật","example":"If I had time, I would travel."}]},{"id":2,"title":"2. Công thức nhanh","type":"formula","formula":"If + present, will + V / If + past, would + V","examples":[{"text":"If water reaches 100°C, it boils.","translated":"Nếu nước đạt 100°C, nó sôi.","highlight":"boils"}]}]}'),
                                                                                           ('Câu so sánh', 'GRAMMAR_LESSON', 'So sánh hơn, so sánh nhất, so sánh bằng và dạng đặc biệt', 6, '{"order":3,"engTitle":"Comparisons","sections":[{"id":1,"title":"1. Công thức so sánh","type":"formula","formula":"adj-er / more adj / the most adj / as adj as","examples":[{"text":"This book is better than that one.","translated":"Cuốn sách này hay hơn cuốn kia.","highlight":"better"}]}]}'),
                                                                                           ('Động từ khuyết thiếu', 'GRAMMAR_LESSON', 'Can, could, must, should, may, might, have to', 6, '{"order":4,"engTitle":"Modal Verbs","sections":[{"id":1,"title":"1. Ý nghĩa chính","type":"usage","items":[{"icon":"lightbulb-on-outline","title":"Khả năng","description":"can, could, may, might","example":"She can swim."},{"icon":"shield-check","title":"Nghĩa vụ","description":"must, have to, should","example":"You must wear a helmet."},{"icon":"comment-question-outline","title":"Đề nghị / lời khuyên","description":"should, ought to","example":"You should rest more."}]}]}'),
                                                                                           ('Mệnh đề quan hệ', 'GRAMMAR_LESSON', 'Who, whom, which, that, whose, where, when', 6, '{"order":1,"engTitle":"Relative Clauses","sections":[{"id":1,"title":"1. Đại từ quan hệ","type":"markers","groups":[{"title":"NGƯỜI","items":["who","whom","whose"]},{"title":"VẬT / SỰ VIỆC","items":["which","that"]},{"title":"NƠI CHỐN / THỜI GIAN","items":["where","when"]}]}]}'),
                                                                                           ('Mệnh đề danh từ', 'GRAMMAR_LESSON', 'Mệnh đề đóng vai trò như danh từ trong câu', 6, '{"order":2,"engTitle":"Noun Clauses","sections":[{"id":1,"title":"1. Vị trí thường gặp","type":"usage","items":[{"icon":"alpha-a-box","title":"Làm chủ ngữ","description":"That he came early surprised everyone.","example":"That he came early surprised everyone."},{"icon":"alpha-c-box","title":"Làm tân ngữ","description":"I know that he is honest.","example":"I know that he is honest."},{"icon":"help-circle-outline","title":"Sau giới từ / tính từ","description":"We are afraid that he is late.","example":"We are afraid that he is late."}]}]}'),
                                                                                           ('Mệnh đề trạng ngữ', 'GRAMMAR_LESSON', 'Mệnh đề chỉ thời gian, nguyên nhân, điều kiện, mục đích, nhượng bộ', 6, '{"order":3,"engTitle":"Adverbial Clauses","sections":[{"id":1,"title":"1. Các loại mệnh đề trạng ngữ","type":"markers","groups":[{"title":"THỜI GIAN","items":["when","after","before","until","while"]},{"title":"NGUYÊN NHÂN","items":["because","since","as"]},{"title":"NHƯỢNG BỘ / MỤC ĐÍCH","items":["although","though","so that"]}]}]}'),
                                                                                           ('Đảo ngữ & câu tường thuật', 'GRAMMAR_LESSON', 'Đảo ngữ, câu tường thuật và cấu trúc nhấn mạnh', 6, '{"order":4,"engTitle":"Inversion and Reported Speech","sections":[{"id":1,"title":"1. Đảo ngữ thường gặp","type":"usage","items":[{"icon":"swap-vertical","title":"Never / Rarely / Seldom","description":"Never have I seen such a view.","example":"Never have I seen such a view."},{"icon":"message-text-outline","title":"Tường thuật câu nói","description":"He said that he was busy.","example":"He said that he was busy."}]}]}');
INSERT INTO learning_lessons (title, type, description, learning_activity_id, content) VALUES
                                                                                           ('Cơ bản', 'GRAMMAR_PRACTICE', 'Present Simple cơ bản', 7, '{"order":1,"difficulty":"Dễ","durationMinutes":10,"grammarLessonTitle":"Hiện tại đơn"}'),
