                                                                                           ('Tổng hợp', 'GRAMMAR_PRACTICE', 'Present Simple tổng hợp', 7, '{"order":3,"difficulty":"Khó","durationMinutes":15,"grammarLessonTitle":"Hiện tại đơn"}'),
                                                                                           ('Cơ bản', 'GRAMMAR_PRACTICE', 'Present Continuous cơ bản', 7, '{"order":1,"difficulty":"Dễ","durationMinutes":10,"grammarLessonTitle":"Hiện tại tiếp diễn"}'),
                                                                                           ('Luyện tập', 'GRAMMAR_PRACTICE', 'Present Continuous luyện tập', 7, '{"order":2,"difficulty":"Trung bình","durationMinutes":12,"grammarLessonTitle":"Hiện tại tiếp diễn"}'),
                                                                                           ('Tổng hợp', 'GRAMMAR_PRACTICE', 'Present Continuous tổng hợp', 7, '{"order":3,"difficulty":"Khó","durationMinutes":15,"grammarLessonTitle":"Hiện tại tiếp diễn"}'),
                                                                                           ('Cơ bản', 'GRAMMAR_PRACTICE', 'Present Perfect cơ bản', 7, '{"order":1,"difficulty":"Dễ","durationMinutes":10,"grammarLessonTitle":"Hiện tại hoàn thành"}'),
                                                                                           ('Luyện tập', 'GRAMMAR_PRACTICE', 'Present Perfect luyện tập', 7, '{"order":2,"difficulty":"Trung bình","durationMinutes":12,"grammarLessonTitle":"Hiện tại hoàn thành"}'),
                                                                                           ('Tổng hợp', 'GRAMMAR_PRACTICE', 'Present Perfect tổng hợp', 7, '{"order":3,"difficulty":"Khó","durationMinutes":15,"grammarLessonTitle":"Hiện tại hoàn thành"}'),
                                                                                           ('Cơ bản', 'GRAMMAR_PRACTICE', 'Present Perfect Continuous cơ bản', 7, '{"order":1,"difficulty":"Dễ","durationMinutes":10,"grammarLessonTitle":"Hiện tại hoàn thành tiếp diễn"}'),
                                                                                           ('Luyện tập', 'GRAMMAR_PRACTICE', 'Present Perfect Continuous luyện tập', 7, '{"order":2,"difficulty":"Trung bình","durationMinutes":12,"grammarLessonTitle":"Hiện tại hoàn thành tiếp diễn"}'),
